// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Library for parsing JSONs.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/JSONParserLib.sol)
library JSONParserLib {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                          STRUCTS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Defines a struct named `Item` with a single field `_data`.
    /// @dev The `_data` field is a `uint256` value. The comment warns against modifying `_data` directly,
    /// suggesting that there may be specific methods or logic to handle its modification.
    struct Item {
        uint256 _data;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CONSTANTS                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    uint256 private constant _BITMASK_TYPE = 0x7;
    uint256 private constant _BITMASK_PARENT_IS_ARRAY = 0x8;
    uint256 private constant _BITMASK_PARENT_IS_OBJECT = 0x10;
    uint256 private constant _BITMASK_PARENT_INDEX = 0xffffffff << 8;
    uint256 private constant _BITMASK_POINTER = 0xffffffff << 32;
    uint256 private constant _BITMASK_STR_LENGTH = 0xffffffff << 32;
    uint256 private constant _BITMASK_INNATE_TYPE = 0x7 << 48;
    uint256 private constant _BITMASK_STR_INNATE_TYPE = 0x7 << 48;

    uint256 private constant _PARENT_IS_ARRAY = 0x8;
    uint256 private constant _PARENT_IS_OBJECT = 0x10;

    uint256 private constant TYPE_UNDEFINED = 0;
    uint256 private constant TYPE_ARRAY = 1;
    uint256 private constant TYPE_OBJECT = 2;
    uint256 private constant TYPE_NUMBER = 3;
    uint256 private constant TYPE_STRING = 4;
    uint256 private constant TYPE_BOOLEAN = 5;
    uint256 private constant TYPE_NULL = 6;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CUSTOM ERRORS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The JSON parsing failed.
    error ParsingFailed();

    /// @dev The JSON string is invalid.
    error InvalidString();

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     PUBLIC FUNCTIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Parses a string input into an `Item` struct using low-level assembly.
    /// @param s The input string to be parsed.
    /// @return result The parsed `Item` struct.
    function parse(string memory s) internal pure returns (Item memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            mstore(0x40, result) // Allocate memory.
            result := _query(s, 0xff)
        }
    }

    /// @notice Retrieves the value of an `Item` by querying it and returning the result as a string.
    /// @param item The `Item` struct whose value is to be retrieved.
    /// @return result The value of the `Item` as a string.
    function value(Item memory item) internal pure returns (string memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := _query(item, 0)
        }
    }

    /// @notice Computes the index of an item in a data structure, specifically handling cases where the item is part of an array.
    /// @param item The item whose index is to be computed.
    /// @return result The computed index of the item.
    function index(Item memory item) internal pure returns (uint256 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let d := mload(item)
            // If the item's parent is an array, the index is stored in the upper bits.
            if and(d, _BITMASK_PARENT_IS_ARRAY) {
                result := shr(8, and(d, _BITMASK_PARENT_INDEX))
            }
        }
    }

    /// @notice Generates a key for a given Item based on its data.
    /// @param item The Item struct containing the data to generate the key from.
    /// @return result The generated key as a string.
    function key(Item memory item) internal pure returns (string memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let d := mload(item)
            // Only objects have keys.
            if and(d, _BITMASK_PARENT_IS_OBJECT) {
                result := _query(item, 1)
            }
        }
    }

    /// @notice Retrieves the child items of a given item by querying the internal data structure.
    /// @param item The item for which the child items are to be retrieved.
    /// @return result An array of child items associated with the given item.
    function children(Item memory item) internal pure returns (Item[] memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := _query(item, 2)
        }
    }

    /// @notice Calculates the size of an `Item` struct in memory.
    /// @param item The `Item` struct whose size is to be determined.
    /// @return result The size of the `Item` struct in memory.
    function size(Item memory item) internal pure returns (uint256 result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := _query(item, 3)
        }
    }

    /// @notice Retrieves an item from a specific index in an array-type item.
    /// @param item The item from which to retrieve the element. Must be of array type.
    /// @param i The index of the element to retrieve.
    /// @return result The item at the specified index, or a zero pointer if the index is invalid or the item is not an array.
    function at(Item memory item, uint256 i) internal pure returns (Item memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            mstore(0x40, result) // Free the default allocation.
            let d := mload(item)
            // Check if the item is of array type.
            if eq(and(d, _BITMASK_TYPE), TYPE_ARRAY) {
                // Perform a low-level query to fetch the array data.
                let q := _query(item, 2)
                // Get the length of the children array.
                let len := mload(q)
                // Check if the index is within bounds.
                if lt(i, len) {
                    // Retrieve the item at the specified index.
                    result := mload(add(q, add(0x20, mul(i, 0x20))))
                }
            }
            // If the index is invalid or the item is not an array, return a zero pointer.
            if iszero(result) {
                result := 0x60
            }
        }
    }

    /// @notice Retrieves an item by key from an object-type item.
    /// @param item The item from which to retrieve the element. Must be of object type.
    /// @param k The key of the element to retrieve.
    /// @return result The item at the specified key, or a zero pointer if the key is invalid or the item is not an object.
    function at(Item memory item, string memory k) internal pure returns (Item memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            mstore(0x40, result) // Free the default allocation.
            let d := mload(item)
            // Check if the item is of object type.
            if eq(and(d, _BITMASK_TYPE), TYPE_OBJECT) {
                // Perform a low-level query to fetch the children data.
                let q := _query(item, 2)
                // Get the length of the children array.
                let len := mload(q)
                // Iterate through the children to find the matching key.
                for { let j := 0 } lt(j, len) { j := add(j, 1) } {
                    let child := mload(add(q, add(0x20, mul(j, 0x20))))
                    let childKey := _query(child, 1)
                    // Compare the keys.
                    if eq(keccak256(add(childKey, 0x20), mload(childKey)), keccak256(add(k, 0x20), mload(k))) {
                        result := child
                        break
                    }
                }
            }
            // If the key is invalid or the item is not an object, return a zero pointer.
            if iszero(result) {
                result := 0x60
            }
        }
    }

    /// @notice Retrieves the type of an item by extracting it from the item's data.
    /// @param item The item whose type is to be retrieved.
    /// @return result The type of the item, extracted from the item's data using a bitmask.
    function getType(Item memory item) internal pure returns (uint8 result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := and(mload(item), _BITMASK_TYPE)
        }
    }

    /// @notice Checks if an Item is undefined by examining its type.
    /// @param item The Item to be checked.
    /// @return result A boolean indicating whether the Item is undefined.
    function isUndefined(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := iszero(and(mload(item), _BITMASK_TYPE))
        }
    }

    /// @notice Checks if the given item is of type array.
    /// @param item The item to check, represented as a struct with a `_data` field.
    /// @return result A boolean indicating whether the item is of type array.
    function isArray(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := eq(and(mload(item), _BITMASK_TYPE), TYPE_ARRAY)
        }
    }

    /// @notice Checks if the given item is of type "Object".
    /// @param item The item to check, represented as a struct of type `Item`.
    /// @return result A boolean indicating whether the item is of type "Object".
    function isObject(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := eq(and(mload(item), _BITMASK_TYPE), TYPE_OBJECT)
        }
    }

    /// @notice Checks if the given `Item` is of type `NUMBER`.
    /// @param item The `Item` struct to be checked.
    /// @return result A boolean indicating whether the `Item` is of type `NUMBER`.
    function isNumber(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := eq(and(mload(item), _BITMASK_TYPE), TYPE_NUMBER)
        }
    }

    /// @notice Checks if the given `Item` is of type string.
    /// @param item The `Item` struct to be checked.
    /// @return result A boolean indicating whether the `Item` is of type string.
    function isString(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := eq(and(mload(item), _BITMASK_TYPE), TYPE_STRING)
        }
    }

    /// @notice Checks if the given `Item` is of type boolean.
    /// @param item The `Item` to check.
    /// @return result A boolean indicating whether the `Item` is of type boolean.
    function isBoolean(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := eq(and(mload(item), _BITMASK_TYPE), TYPE_BOOLEAN)
        }
    }

    /// @notice Checks if the given `Item` is of type `TYPE_NULL`.
    /// @param item The `Item` struct to be checked.
    /// @return result A boolean indicating whether the `Item` is of type `TYPE_NULL`.
    function isNull(Item memory item) internal pure returns (bool result) {
        /// @solidity memory-safe-assembly
        assembly {
            result := eq(and(mload(item), _BITMASK_TYPE), TYPE_NULL)
        }
    }

    /// @notice Retrieves the parent item from the given item in a memory-safe manner.
    /// @param item The input item from which the parent is to be extracted.
    /// @return result The parent item, or the zero pointer if no parent exists.
    function parent(Item memory item) internal pure returns (Item memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            mstore(0x40, result) // Free the default allocation.
            let d := mload(item)
            // The parent pointer is stored in the upper bits.
            result := shr(32, and(d, _BITMASK_POINTER))
            // If the result is zero, reset it to the zero pointer.
            if iszero(result) {
                result := 0x60
            }
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     PARSING FUNCTIONS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Parses a string representation of a number into a uint256 value.
    /// @param s The string to parse into a uint256.
    /// @return result The parsed uint256 value.
    function parseUint(string memory s) internal pure returns (uint256 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(s)
            if iszero(n) {
                revert(0, 0)
            }
            let p := add(s, 0x20)
            let end := add(p, n)
            result := 0
            let preMulOverflowThres := div(not(0), 10)
            for {} 1 {} {
                let c := byte(0, mload(p))
                // Break if not a digit.
                if iszero(and(gt(c, 47), lt(c, 58))) {
                    break
                }
                // Check for overflow.
                if gt(result, preMulOverflowThres) {
                    revert(0, 0)
                }
                result := add(mul(result, 10), sub(c, 48))
                p := add(p, 1)
                if iszero(lt(p, end)) {
                    break
                }
            }
            // Check if we processed all characters.
            if iszero(eq(p, end)) {
                revert(0, 0)
            }
        }
    }

    /// @notice Parses a string representation of a number into an integer.
    /// @param s The string to be parsed into an integer.
    /// @return result The parsed integer value.
    function parseInt(string memory s) internal pure returns (int256 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(s)
            if iszero(n) {
                revert(0, 0)
            }
            let p := add(s, 0x20)
            let end := add(p, n)
            let sign := 1
            let c := byte(0, mload(p))
            // Check for sign.
            if eq(c, 43) { // '+'
                p := add(p, 1)
            }
            if eq(c, 45) { // '-'
                sign := -1
                p := add(p, 1)
            }
            // Parse the number.
            let r := 0
            let preMulOverflowThres := div(not(0), 10)
            for {} lt(p, end) {} {
                c := byte(0, mload(p))
                // Break if not a digit.
                if iszero(and(gt(c, 47), lt(c, 58))) {
                    break
                }
                // Check for overflow.
                if gt(r, preMulOverflowThres) {
                    revert(0, 0)
                }
                r := add(mul(r, 10), sub(c, 48))
                p := add(p, 1)
            }
            // Check if we processed all characters.
            if iszero(eq(p, end)) {
                revert(0, 0)
            }
            // Handle negative numbers and overflow.
            if eq(sign, -1) {
                if gt(r, add(uint256(type(int256).max), 1)) {
                    revert(0, 0)
                }
                result := sub(0, r)
            }
            if eq(sign, 1) {
                if gt(r, uint256(type(int256).max)) {
                    revert(0, 0)
                }
                result := r
            }
        }
    }

    /// @notice Parses a hexadecimal string into a uint256 value.
    /// @param s The hexadecimal string to parse.
    /// @return result The parsed uint256 value.
    function parseUintFromHex(string memory s) internal pure returns (uint256 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(s)
            if iszero(n) {
                revert(0, 0)
            }
            let p := add(s, 0x20)
            let end := add(p, n)
            // Skip '0x' or '0X' prefix.
            if and(gt(n, 1), eq(byte(0, mload(p)), 48)) {
                let c := byte(0, mload(add(p, 1)))
                if or(eq(c, 120), eq(c, 88)) { // 'x' or 'X'
                    p := add(p, 2)
                }
            }
            result := 0
            for {} lt(p, end) {} {
                let c := byte(0, mload(p))
                // Convert hex character to value.
                let v := 0
                if and(gt(c, 47), lt(c, 58)) { // '0'-'9'
                    v := sub(c, 48)
                }
                if and(gt(c, 64), lt(c, 71)) { // 'A'-'F'
                    v := sub(c, 55)
                }
                if and(gt(c, 96), lt(c, 103)) { // 'a'-'f'
                    v := sub(c, 87)
                }
                // Check for invalid characters.
                if iszero(or(or(and(gt(c, 47), lt(c, 58)), and(gt(c, 64), lt(c, 71))), and(gt(c, 96), lt(c, 103)))) {
                    revert(0, 0)
                }
                result := add(shl(4, result), v)
                p := add(p, 1)
            }
        }
    }

    /// @notice Decodes a string that may contain Unicode escape sequences into a valid UTF-8 string.
    /// @param s The input string to decode, which may contain escape sequences.
    /// @return result The decoded UTF-8 string.
    function decodeString(string memory s) internal pure returns (string memory result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(s)
            // Must be at least 2 characters (double quotes).
            if lt(n, 2) {
                revert(0, 0)
            }
            let p := add(s, 0x20)
            let end := add(p, n)
            // Check for double quotes.
            if iszero(eq(byte(0, mload(p)), 34)) { // '"'
                revert(0, 0)
            }
            if iszero(eq(byte(0, mload(sub(end, 1))), 34)) { // '"'
                revert(0, 0)
            }
            // Skip the opening quote.
            p := add(p, 1)
            // Remove the closing quote.
            end := sub(end, 1)
            // Allocate memory for the result.
            result := mload(0x40)
            // Store the length later.
            let resultStart := add(result, 0x20)
            let r := resultStart
            for {} lt(p, end) {} {
                let c := byte(0, mload(p))
                // Handle escape sequences.
                if eq(c, 92) { // '\\'
                    p := add(p, 1)
                    if iszero(lt(p, end)) {
                        revert(0, 0)
                    }
                    c := byte(0, mload(p))
                    // Standard escape sequences.
                    if eq(c, 34) { mstore8(r, 34) } // '\"'
                    if eq(c, 92) { mstore8(r, 92) } // '\\'
                    if eq(c, 47) { mstore8(r, 47) } // '/'
                    if eq(c, 98) { mstore8(r, 8) } // '\b'
                    if eq(c, 102) { mstore8(r, 12) } // '\f'
                    if eq(c, 110) { mstore8(r, 10) } // '\n'
                    if eq(c, 114) { mstore8(r, 13) } // '\r'
                    if eq(c, 116) { mstore8(r, 9) } // '\t'
                    // Unicode escape sequence.
                    if eq(c, 117) { // 'u'
                        p := add(p, 1)
                        if lt(p, end) {
                            let u := 0
                            // Parse 4 hex digits.
                            for { let i := 0 } lt(i, 4) { i := add(i, 1) } {
                                if iszero(lt(p, end)) {
                                    revert(0, 0)
                                }
                                c := byte(0, mload(p))
                                let v := 0
                                if and(gt(c, 47), lt(c, 58)) { v := sub(c, 48) }
                                if and(gt(c, 64), lt(c, 71)) { v := sub(c, 55) }
                                if and(gt(c, 96), lt(c, 103)) { v := sub(c, 87) }
                                if iszero(or(or(and(gt(c, 47), lt(c, 58)), and(gt(c, 64), lt(c, 71))), and(gt(c, 96), lt(c, 103)))) {
                                    revert(0, 0)
                                }
                                u := add(shl(4, u), v)
                                p := add(p, 1)
                            }
                            // Encode as UTF-8.
                            if lt(u, 0x80) {
                                mstore8(r, u)
                                r := add(r, 1)
                            }
                            if and(gt(u, 0x7f), lt(u, 0x800)) {
                                mstore8(r, add(0xc0, shr(6, u)))
                                r := add(r, 1)
                                mstore8(r, add(0x80, and(u, 0x3f)))
                                r := add(r, 1)
                            }
                            if and(gt(u, 0x7ff), lt(u, 0x10000)) {
                                mstore8(r, add(0xe0, shr(12, u)))
                                r := add(r, 1)
                                mstore8(r, add(0x80, and(shr(6, u), 0x3f)))
                                r := add(r, 1)
                                mstore8(r, add(0x80, and(u, 0x3f)))
                                r := add(r, 1)
                            }
                            // Handle surrogate pairs (not fully implemented for simplicity).
                            if gt(u, 0xffff) {
                                revert(0, 0)
                            }
                        }
                    }
                }
                // Normal character.
                if iszero(eq(c, 92)) {
                    mstore8(r, c)
                    r := add(r, 1)
                }
                p := add(p, 1)
            }
            // Store the length.
            let len := sub(r, resultStart)
            mstore(result, len)
            // Null-terminate the string.
            mstore8(r, 0)
            // Update the free memory pointer.
            mstore(0x40, add(r, 0x20))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                    PRIVATE FUNCTIONS                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev A function `_query` that processes a bytes32 input based on the specified mode.
    /// Modes:
    /// 0: Retrieves the value associated with the input.
    /// 1: Retrieves the key associated with the input.
    /// 2: Retrieves the children associated with the input.
    /// 3: Retrieves the size of the item.
    /// 0xff: Parses the input as a JSON-like structure and returns the parsed result.
    function _query(bytes32 input, uint256 mode) private pure returns (bytes32 result) {
        // This is a placeholder. The actual implementation requires complex assembly
        // for JSON parsing, memory management, and query handling.
        // The full implementation would involve:
        // - Memory allocation helpers (mallocItem, etc.)
        // - JSON tokenizers (parseValue, parseArray, parseObject, etc.)
        // - String handling (parseStringSub, copyStr, etc.)
        // - Value extraction (value, children, getStr, etc.)
        assembly {
            // Helper functions.
            function fail() {
                mstore(0x00, 0xd6bda275) // `ParsingFailed()`.
                revert(0x1c, 0x04)
            }
            function chr(p_) -> c_ {
                c_ := byte(0, mload(p_))
            }
            function skipWhitespace(pIn_, end_) -> p_ {
                p_ := pIn_
                for {} lt(p_, end_) {} {
                    let c_ := chr(p_)
