                    if eq(c, 98) { mstore8(r, 8) } // '\b'
                    if eq(c, 102) { mstore8(r, 12) } // '\f'
                    if eq(c, 110) { mstore8(r, 10) } // '\n'
                    if eq(c, 114) { mstore8(r, 13) } // '\r'
                    if eq(c, 116) { mstore8(r, 9) } // '\t'
                    // Unicode escape sequence.
